from itertools import permutations

def d(p):
    return sum(abs(p[k]-(k+1)) for k in range(len(p)))

def inv(p):
    n = len(p)
    c = 0
    for i in range(n):
        for j in range(i+1,n):
            if p[i] > p[j]:
                c += 1
    return c

# Check if i(p) <= d(p) for all permutations up to n=9
for n in range(2, 10):
    max_ratio = 0
    violated = False
    for p in permutations(range(1, n+1)):
        dd = d(p)
        if dd == 0:
            continue
        ii = inv(p)
        if ii > dd:
            violated = True
            print(f'VIOLATION: n={n}, p={p}, i={ii}, d={dd}')
        r = ii / dd
        if r > max_ratio:
            max_ratio = r
    print(f'n={n}: max i/d = {max_ratio:.6f}, i<=d always: {not violated}')
"

